internal static class ImportFields
{
    internal static string? V(MasterDataRawRow r,string k)=>r.Values.TryGetValue(k,out var v)?v?.Trim():null;
    internal static string Code(string? v)=>(v??string.Empty).Trim().ToUpperInvariant();
    internal static MasterDataRowError Error(string k,string h,string c,string m,string? v)=>new(k,h,c,m,v);
    internal static void Required(MasterDataRawRow r,string k,string h,List<MasterDataRowError> e){if(string.IsNullOrWhiteSpace(V(r,k)))e.Add(Error(k,h,"REQUIRED",$"{h} is required.",V(r,k)));}
    internal static bool Bool(MasterDataRawRow r,string k,List<MasterDataRowError> e){var v=V(r,k);if(bool.TryParse(v,out var b))return b;e.Add(Error(k,k,"INVALID_VALUE",$"{k} must be TRUE or FALSE.",v));return false;}
    internal static decimal Decimal(MasterDataRawRow r,string k,List<MasterDataRowError> e){var v=V(r,k);if(decimal.TryParse(v,NumberStyles.Number,CultureInfo.InvariantCulture,out var d)&&d>=0)return d;e.Add(Error(k,k,"INVALID_VALUE",$"{k} must be a non-negative invariant decimal.",v));return 0;}
    internal static DateOnly? Date(MasterDataRawRow r,string k,List<MasterDataRowError> e){var v=V(r,k);if(string.IsNullOrWhiteSpace(v))return null;if(DateOnly.TryParseExact(v,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out var d))return d;e.Add(Error(k,k,"INVALID_VALUE",$"{k} must use YYYY-MM-DD.",v));return null;}
    internal static IReadOnlyList<string> Codes(string? value)=>string.IsNullOrWhiteSpace(value)?[]:value.Split([',',';'],StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).Select(Code).Distinct(StringComparer.Ordinal).ToArray();
    internal static MasterDataColumnDefinition C(string k,string h,MasterDataColumnType t,bool required,string format,string allowed,string description,string? lookup=null)=>new(k,h,t,required,required,true,format,allowed,lookup,description);
    internal static MasterDataColumnDefinition R(string k,string h,MasterDataColumnType t)=>new(k,h,t,false,false,false,"Read-only","Exported value",null,"Read-only identity, lifecycle or concurrency value.");
    internal static MasterDataExportRow Example(params (string Key,object? Value)[] values)=>new(values.ToDictionary(x=>x.Key,x=>x.Value,StringComparer.Ordinal));
    internal static MasterDataExistingSet Set(IEnumerable<MasterDataExistingRecord> rows)=>new(rows.ToDictionary(x=>x.NormalizedBusinessCode,StringComparer.Ordinal),rows.ToDictionary(x=>x.Id));
}

