public sealed class ItemMasterDataAdapter(NexaErpDbContext db,ICurrentUser user) : IMasterDataAdapter
{
    public IMasterDataDefinition Definition {get;}=new ItemImportDefinition(); public string NormalizeBusinessCode(string v)=>ImportFields.Code(v);
    public async Task<IReadOnlyList<MasterDataExportRow>> ExportAsync(MasterDataExportQuery q,CancellationToken ct)=>await db.Items.AsNoTracking().OrderBy(x=>x.ItemCode).Select(x=>new MasterDataExportRow(new Dictionary<string,object?>{{"RecordId",x.Id},{"Version",x.Version},{"ItemCode",x.ItemCode},{"Name",x.Name},{"ItemType",x.ItemType},{"IsReturnable",x.IsReturnable},{"HsnSacCode",x.HsnSacCode},{"GstPercentage",x.GstPercentage},{"UomCode",x.Uom},{"CategoryCode",x.Category==null?null:x.Category.Code},{"SubcategoryCode",x.Subcategory==null?null:x.Subcategory.Code},{"ManufacturerCode",x.Manufacturer==null?null:x.Manufacturer.Code},{"PreferredVendorCode",x.PreferredVendor==null?null:x.PreferredVendor.VendorCode},{"SerialPolicy",x.SerialNumberTracking?"SERIAL":x.BatchTracking?"BATCH":x.ShelfLifeTracking?"SHELF_LIFE":"NONE"},{"ReorderLevel",x.ReorderLevel},{"Status",x.Status},{"ApprovalStatus",x.ApprovalStatus}})).ToListAsync(ct);
    public async Task<MasterDataExistingSet> LoadExistingAsync(IReadOnlyCollection<string> codes,IReadOnlyCollection<Guid> ids,CancellationToken ct){var rows=await db.Items.AsNoTracking().Where(x=>codes.Contains(x.ItemCode)||ids.Contains(x.Id)).Select(x=>new MasterDataExistingRecord(x.Id,x.ItemCode,x.ItemCode,x.Version,new Dictionary<string,string?>{{"ItemCode",x.ItemCode},{"Name",x.Name},{"ItemType",x.ItemType},{"IsReturnable",x.IsReturnable.ToString()},{"HsnSacCode",x.HsnSacCode},{"GstPercentage",x.GstPercentage.ToString(CultureInfo.InvariantCulture)},{"UomCode",x.Uom},{"ReorderLevel",x.ReorderLevel.ToString(CultureInfo.InvariantCulture)},{"Status",x.Status},{"ApprovalStatus",x.ApprovalStatus}})).ToListAsync(ct);return ImportFields.Set(rows);}
    public async Task<object?> LoadLookupContextAsync(IReadOnlyList<MasterDataRawRow> rows,CancellationToken ct)=>new ItemLookup(await db.Uoms.Where(x=>x.IsActive).ToDictionaryAsync(x=>x.Code,x=>x.Id,ct),await db.ItemCategories.Where(x=>x.IsActive).ToDictionaryAsync(x=>x.Code,x=>x.Id,ct),await db.ItemSubcategories.Where(x=>x.IsActive).ToDictionaryAsync(x=>x.Code,x=>new ValueTuple<Guid,Guid>(x.Id,x.CategoryId),ct),await db.Manufacturers.Where(x=>x.IsActive).ToDictionaryAsync(x=>x.Code,x=>x.Id,ct),await db.Vendors.Where(x=>x.IsActive).ToDictionaryAsync(x=>x.VendorCode,x=>x.Id,ct));
    public IReadOnlyList<MasterDataRowError> Validate(MasterDataRawRow r,MasterDataExistingRecord? existing,object? context){var e=new List<MasterDataRowError>();foreach(var x in new[]{("ItemCode","Item Code"),("Name","Item Name"),("ItemType","Item Type"),("IsReturnable","Is Returnable"),("HsnSacCode","HSN / SAC Code"),("UomCode","UOM Code"),("CategoryCode","Category Code"),("SerialPolicy","Serial Policy"),("ReorderLevel","Reorder Level")})ImportFields.Required(r,x.Item1,x.Item2,e);ImportFields.Bool(r,"IsReturnable",e);ImportFields.Decimal(r,"GstPercentage",e);ImportFields.Decimal(r,"ReorderLevel",e);var itemType=ImportFields.Code(ImportFields.V(r,"ItemType"));if(!ItemTypes.All.Contains(itemType))e.Add(ImportFields.Error("ItemType","Item Type","INVALID_VALUE","Use a documented item type.",itemType));var policy=ImportFields.Code(ImportFields.V(r,"SerialPolicy"));if(!new[]{"NONE","SERIAL","BATCH","SHELF_LIFE"}.Contains(policy))e.Add(ImportFields.Error("SerialPolicy","Serial Policy","INVALID_VALUE","Use NONE, SERIAL, BATCH or SHELF_LIFE.",policy));if(context is ItemLookup l){Check(l.Uoms,"UomCode","UOM Code",true);Check(l.Categories,"CategoryCode","Category Code",true);Check(l.Manufacturers,"ManufacturerCode","Manufacturer Code",false);Check(l.Vendors,"PreferredVendorCode","Preferred Vendor Code",false);var sub=ImportFields.Code(ImportFields.V(r,"SubcategoryCode"));if(sub.Length>0&&(!l.Subcategories.TryGetValue(sub,out var s)||!l.Categories.TryGetValue(ImportFields.Code(ImportFields.V(r,"CategoryCode")),out var c)||s.CategoryId!=c))e.Add(ImportFields.Error("SubcategoryCode","Subcategory Code","LOOKUP_NOT_FOUND","Subcategory was not found under the selected category.",sub));void Check(Dictionary<string,Guid> d,string k,string h,bool req){var v=ImportFields.Code(ImportFields.V(r,k));if((req||v.Length>0)&&!d.ContainsKey(v))e.Add(ImportFields.Error(k,h,"LOOKUP_NOT_FOUND",$"Active {h} was not found.",v));}}if(existing is not null&&existing.MaterialValues.TryGetValue("Status",out var status)&&status!="DRAFT")e.Add(ImportFields.Error("ItemCode","Item Code","GOVERNED_RECORD","Only Draft items may be changed by import.",existing.BusinessCode));return e;}
    public bool IsMateriallyEqual(MasterDataRawRow r,MasterDataExistingRecord x)=>false;
    public async Task<MasterDataApplyResult> CreateAsync(MasterDataRawRow r,CancellationToken ct){var l=(ItemLookup)(await LoadLookupContextAsync([r],ct))!;var item=new Item{ItemCode=ImportFields.Code(ImportFields.V(r,"ItemCode")),Name=ImportFields.V(r,"Name")!,DetailedDescription=ImportFields.V(r,"Name")!,ItemType=ImportFields.Code(ImportFields.V(r,"ItemType")),MaterialType=ImportFields.Code(ImportFields.V(r,"CategoryCode")),IsReturnable=bool.Parse(ImportFields.V(r,"IsReturnable")!),HsnSacCode=ImportFields.V(r,"HsnSacCode"),GstPercentage=decimal.Parse(ImportFields.V(r,"GstPercentage")!,CultureInfo.InvariantCulture),Uom=ImportFields.Code(ImportFields.V(r,"UomCode")),UomId=l.Uoms[ImportFields.Code(ImportFields.V(r,"UomCode"))],BaseUomId=l.Uoms[ImportFields.Code(ImportFields.V(r,"UomCode"))],CategoryId=l.Categories[ImportFields.Code(ImportFields.V(r,"CategoryCode"))],SubcategoryId=Id(l.Subcategories,ImportFields.V(r,"SubcategoryCode")),ManufacturerId=Id(l.Manufacturers,ImportFields.V(r,"ManufacturerCode")),PreferredVendorId=Id(l.Vendors,ImportFields.V(r,"PreferredVendorCode")),ReorderLevel=decimal.Parse(ImportFields.V(r,"ReorderLevel")!,CultureInfo.InvariantCulture),Status=MasterStatuses.Draft,ApprovalStatus=MasterApprovalStatuses.Draft,IsActive=true,CreatedBy=user.LoginId};SetPolicy(item,ImportFields.Code(ImportFields.V(r,"SerialPolicy")));db.Items.Add(item);await db.SaveChangesAsync(ct);return new(item.Id,item.Version);}
    public async Task<MasterDataApplyResult> UpdateAsync(MasterDataExistingRecord x,MasterDataRawRow r,uint version,CancellationToken ct){var item=await db.Items.SingleAsync(y=>y.Id==x.Id&&y.Version==version,ct);var l=(ItemLookup)(await LoadLookupContextAsync([r],ct))!;item.Name=ImportFields.V(r,"Name")!;item.DetailedDescription=item.Name;item.ItemType=ImportFields.Code(ImportFields.V(r,"ItemType"));item.MaterialType=ImportFields.Code(ImportFields.V(r,"CategoryCode"));item.IsReturnable=bool.Parse(ImportFields.V(r,"IsReturnable")!);item.HsnSacCode=ImportFields.V(r,"HsnSacCode");item.GstPercentage=decimal.Parse(ImportFields.V(r,"GstPercentage")!,CultureInfo.InvariantCulture);item.Uom=ImportFields.Code(ImportFields.V(r,"UomCode"));item.UomId=item.BaseUomId=l.Uoms[item.Uom];item.CategoryId=l.Categories[ImportFields.Code(ImportFields.V(r,"CategoryCode"))];item.SubcategoryId=Id(l.Subcategories,ImportFields.V(r,"SubcategoryCode"));item.ManufacturerId=Id(l.Manufacturers,ImportFields.V(r,"ManufacturerCode"));item.PreferredVendorId=Id(l.Vendors,ImportFields.V(r,"PreferredVendorCode"));item.ReorderLevel=decimal.Parse(ImportFields.V(r,"ReorderLevel")!,CultureInfo.InvariantCulture);item.UpdatedAt=DateTimeOffset.UtcNow;item.UpdatedBy=user.LoginId;SetPolicy(item,ImportFields.Code(ImportFields.V(r,"SerialPolicy")));await db.SaveChangesAsync(ct);return new(item.Id,item.Version);}
    private static Guid? Id(Dictionary<string,Guid> d,string? v)=>d.TryGetValue(ImportFields.Code(v),out var id)?id:null;private static Guid? Id(Dictionary<string,(Guid Id,Guid CategoryId)> d,string? v)=>d.TryGetValue(ImportFields.Code(v),out var x)?x.Id:null;private static void SetPolicy(Item i,string p){i.SerialNumberTracking=p=="SERIAL";i.BatchTracking=p=="BATCH";i.ShelfLifeTracking=p=="SHELF_LIFE";}
}

