internal sealed record ItemVendorLookup(Dictionary<string,Guid> Items,Dictionary<string,Guid> Vendors);
public sealed class ItemVendorMasterDataAdapter(NexaErpDbContext db,ICurrentUser user):IMasterDataAdapter
{
    public IMasterDataDefinition Definition{get;}=new ItemVendorImportDefinition();public string NormalizeBusinessCode(string v)=>ImportFields.Code(v);
    public async Task<IReadOnlyList<MasterDataExportRow>> ExportAsync(MasterDataExportQuery q,CancellationToken ct)=>await db.ItemVendors.AsNoTracking().OrderBy(x=>x.Item!.ItemCode).ThenBy(x=>x.Vendor!.VendorCode).Select(x=>new MasterDataExportRow(new Dictionary<string,object?>{{"RecordId",x.Id},{"Version",x.Version},{"LinkCode",x.Item!.ItemCode+"|"+x.Vendor!.VendorCode},{"ItemCode",x.Item.ItemCode},{"VendorCode",x.Vendor.VendorCode}})).ToListAsync(ct);
