    public async Task<object?> LoadLookupContextAsync(IReadOnlyList<MasterDataRawRow> r,CancellationToken ct)=>new ItemVendorLookup(await db.Items.Where(x=>x.IsActive).ToDictionaryAsync(x=>x.ItemCode,x=>x.Id,ct),await db.Vendors.Where(x=>x.IsActive).ToDictionaryAsync(x=>x.VendorCode,x=>x.Id,ct));
    public IReadOnlyList<MasterDataRowError> Validate(MasterDataRawRow r,MasterDataExistingRecord? x,object? context){var e=new List<MasterDataRowError>();foreach(var f in new[]{("LinkCode","Link Code"),("ItemCode","Item Code"),("VendorCode","Vendor Code")})ImportFields.Required(r,f.Item1,f.Item2,e);var item=ImportFields.Code(ImportFields.V(r,"ItemCode"));var vendor=ImportFields.Code(ImportFields.V(r,"VendorCode"));if(ImportFields.Code(ImportFields.V(r,"LinkCode"))!=item+"|"+vendor)e.Add(ImportFields.Error("LinkCode","Link Code","PAIR_MISMATCH","Link Code must equal ITEMCODE|VENDORCODE.",ImportFields.V(r,"LinkCode")));if(context is ItemVendorLookup l){if(!l.Items.ContainsKey(item))e.Add(ImportFields.Error("ItemCode","Item Code","LOOKUP_NOT_FOUND","Active item was not found.",item));if(!l.Vendors.ContainsKey(vendor))e.Add(ImportFields.Error("VendorCode","Vendor Code","LOOKUP_NOT_FOUND","Active vendor was not found.",vendor));}return e;}public bool IsMateriallyEqual(MasterDataRawRow r,MasterDataExistingRecord x)=>true;
