public sealed class OpeningStockImportDefinition:IMasterDataDefinition
{
    public string MasterKey=>"opening-stock";public int TemplateVersion=>1;public string PageKey=>"stores.opening-stock";public string BusinessCodeColumnKey=>"LineReference";public IReadOnlyList<string> OperationalRolePriority=>["STORES_MANAGER","ACCOUNTS_MANAGER","TECHNICAL_DIRECTOR"];public MasterDataSensitivePermission? SensitiveResultPermission=>null;
